svg.defs:
        /* haider.digital brand theme */
svg {
  color: #A8A49A !important;
  background-color: #0A0A0A !important;
}
.items-wrapper {
  background: #0A0A0A !important;
  padding: 10px 8px 8px !important;
  box-sizing: border-box !important;
}
h1, h2, h3 {
  color: #F0EDE8 !important;
}
h1 svg, h2 svg, h3 svg {
  fill: #F0EDE8 !important;
}
.field {
  color: #A8A49A !important;
}
.field svg {
  fill: #A8A49A !important;
}
footer {
  color: #6E6A63 !important;
}
.field.language.details small,
.field.license.details small {
  color: #6E6A63 !important;
}
:root {
  --color-calendar-graph-day-bg: #1A1A1A;
  --color-calendar-graph-day-border: rgba(240,237,232,0.08);
  --color-calendar-graph-day-L1-bg: #3A3834;
  --color-calendar-graph-day-L2-bg: #6E6A63;
  --color-calendar-graph-day-L3-bg: #A8A49A;
  --color-calendar-graph-day-L4-bg: #F0EDE8;
  --color-calendar-graph-day-L1-border: rgba(240,237,232,0.06);
  --color-calendar-graph-day-L2-border: rgba(240,237,232,0.06);
  --color-calendar-graph-day-L3-border: rgba(240,237,232,0.06);
  --color-calendar-graph-day-L4-border: rgba(240,237,232,0.06);
}
.contribution.organization {
  border-color: #A8A49A !important;
  background-color: rgba(240,237,232,0.06) !important;
  color: #F0EDE8 !important;
}
.contribution.organization.s,
.contribution.organization.a,
.contribution.organization.b,
.contribution.organization.c {
  color: #F0EDE8 !important;
  border-color: #A8A49A !important;
  background-color: rgba(240,237,232,0.08) !important;
}
